import{_ as e,o as a,c as i,a5 as r}from"./chunks/framework.Bt0SrEfo.js";const b=JSON.parse('{"title":"性能优化清单(发布前必看)","description":"","frontmatter":{},"headers":[],"relativePath":"performance/7-checklist.md","filePath":"performance/7-checklist.md","lastUpdated":1789979447000}'),o={name:"performance/7-checklist.md"};function t(h,l,n,u,s,d){return a(),i("div",null,[...l[0]||(l[0]=[r('<h1 id="性能优化清单-发布前必看" tabindex="-1">性能优化清单(发布前必看) <a class="header-anchor" href="#性能优化清单-发布前必看" aria-label="Permalink to &quot;性能优化清单(发布前必看)&quot;">​</a></h1><blockquote><p>复制这份到 PR 模板 / 评审 Checklist,逐项打勾。</p></blockquote><h2 id="一、加载性能" tabindex="-1">一、加载性能 <a class="header-anchor" href="#一、加载性能" aria-label="Permalink to &quot;一、加载性能&quot;">​</a></h2><h3 id="资源层" tabindex="-1">资源层 <a class="header-anchor" href="#资源层" aria-label="Permalink to &quot;资源层&quot;">​</a></h3><ul><li>[ ] 启用 HTTP/2(或 HTTP/3) —— 多路复用,握手成本降一半</li><li>[ ] 启用 Brotli 压缩 —— 比 gzip 再小 15~20%</li><li>[ ] 静态资源走 CDN —— 用户就近访问</li><li>[ ] 关键 CSS 内联到 head —— 避免首屏白屏</li><li>[ ] preload 关键资源(LCP 图片 / 字体) —— 提前下载</li><li>[ ] preconnect / dns-prefetch 第三方域名 —— 减少 DNS 查询</li><li>[ ] 字体 preload + font-display: swap —— 避免文字闪烁</li></ul><h3 id="图片-视频" tabindex="-1">图片/视频 <a class="header-anchor" href="#图片-视频" aria-label="Permalink to &quot;图片/视频&quot;">​</a></h3><ul><li>[ ] 图片显式 width / height —— 避免 CLS</li><li>[ ] 首屏图片用 AVIF/WebP —— 比 JPG 小 30~50%</li><li>[ ] 非首屏图片 loading=&quot;lazy&quot; —— 延迟加载</li><li>[ ] 大图标用 SVG / iconfont —— 比 PNG 小</li></ul><h3 id="js-字体" tabindex="-1">JS / 字体 <a class="header-anchor" href="#js-字体" aria-label="Permalink to &quot;JS / 字体&quot;">​</a></h3><ul><li>[ ] 代码分割:路由懒加载 —— 首屏不加载其他页面</li><li>[ ] tree-shaking 验证 —— 打包后无未引用代码</li><li>[ ] 第三方库按需引入 —— element-plus / antd / lodash 全量是反模式</li><li>[ ] 字体子集化 —— 中文字体只引入用到的字符</li></ul><h2 id="二、运行时性能" tabindex="-1">二、运行时性能 <a class="header-anchor" href="#二、运行时性能" aria-label="Permalink to &quot;二、运行时性能&quot;">​</a></h2><h3 id="渲染" tabindex="-1">渲染 <a class="header-anchor" href="#渲染" aria-label="Permalink to &quot;渲染&quot;">​</a></h3><ul><li>[ ] 列表 &gt; 100 行用虚拟列表 —— react-window / virtuoso</li><li>[ ] React.memo / useMemo / useCallback 包裹重组件 —— 避免不必要重渲染</li><li>[ ] v-memo / v-once(Vue 3) —— 同样避免重渲染</li><li>[ ] 长任务拆分:await scheduler.yield() —— 让出主线程</li><li>[ ] requestAnimationFrame 动画 —— 不在定时器里做动画</li><li>[ ] requestIdleCallback 后台任务 —— 不阻塞用户交互</li></ul><h3 id="数据" tabindex="-1">数据 <a class="header-anchor" href="#数据" aria-label="Permalink to &quot;数据&quot;">​</a></h3><ul><li>[ ] 防抖 / 节流 —— 滚动、resize、input 都要</li><li>[ ] Web Worker 处理大数据 —— &gt; 16ms 的任务考虑 Worker</li><li>[ ] 计算属性 vs 方法(Vue) —— computed 自带缓存</li></ul><h3 id="表单-输入" tabindex="-1">表单/输入 <a class="header-anchor" href="#表单-输入" aria-label="Permalink to &quot;表单/输入&quot;">​</a></h3><ul><li>[ ] 不在 onChange 里同步发请求 —— 用 blur 或防抖</li><li>[ ] 受控组件 debounce —— 避免每输入一次就 re-render</li></ul><h2 id="三、内存管理" tabindex="-1">三、内存管理 <a class="header-anchor" href="#三、内存管理" aria-label="Permalink to &quot;三、内存管理&quot;">​</a></h2><blockquote><p>7x24 小时运行 / 路由频繁切换 / 单页应用尤其重要。</p></blockquote><ul><li>[ ] beforeUnmount / unmounted 清理定时器</li><li>[ ] ECharts / Highcharts 实例 dispose</li><li>[ ] Three.js / Babylon.js 场景 destroy</li><li>[ ] EventBus / EventEmitter 解绑</li><li>[ ] AbortController 取消未完成请求</li><li>[ ] Web Worker terminate</li><li>[ ] 大的 Blob / File / ArrayBuffer 不再用时置 null</li><li>[ ] 闭包内引用的 DOM 节点 / 大对象,在不需要时置 null</li></ul><h2 id="四、网络" tabindex="-1">四、网络 <a class="header-anchor" href="#四、网络" aria-label="Permalink to &quot;四、网络&quot;">​</a></h2><ul><li>[ ] API 请求合并:GraphQL / BFF —— 减少请求数</li><li>[ ] 客户端缓存:SWR / React Query / Pinia —— 减少重复请求</li><li>[ ] HTTP 缓存:Cache-Control / ETag —— 静态资源强缓存</li><li>[ ] Service Worker 缓存关键资源 —— PWA 必备</li><li>[ ] 接口防重 / 防抖 —— 避免重复点击</li><li>[ ] WebSocket 断线重连 —— 业务侧容错</li></ul><h2 id="五、监控" tabindex="-1">五、监控 <a class="header-anchor" href="#五、监控" aria-label="Permalink to &quot;五、监控&quot;">​</a></h2><ul><li>[ ] Web Vitals 自动上报(LCP / INP / CLS)</li><li>[ ] 长任务监控(PerformanceObserver)</li><li>[ ] 错误监控(Sentry / 自建)</li><li>[ ] 业务关键路径耗时打点</li><li>[ ] 上线后 1 周复查 RUM 看板</li></ul><h2 id="六、上线前最后检查" tabindex="-1">六、上线前最后检查 <a class="header-anchor" href="#六、上线前最后检查" aria-label="Permalink to &quot;六、上线前最后检查&quot;">​</a></h2><ul><li>[ ] Lighthouse 综合分 ≥ 90(内部页)/ ≥ 70(用户页)</li><li>[ ] 包体积报警阈值(主 chunk &lt; 500KB / 总和 &lt; 2MB)</li><li>[ ] 真实设备测试(iOS Safari、Android Chrome)</li><li>[ ] 弱网测试(Chrome DevTools Slow 3G)</li><li>[ ] 慢 CPU 测试(DevTools 4x slowdown)</li><li>[ ] 灰度发布,观察 1 天再全量</li></ul><h2 id="七、按场景的快速清单" tabindex="-1">七、按场景的快速清单 <a class="header-anchor" href="#七、按场景的快速清单" aria-label="Permalink to &quot;七、按场景的快速清单&quot;">​</a></h2><h3 id="中后台管理系统" tabindex="-1">中后台管理系统 <a class="header-anchor" href="#中后台管理系统" aria-label="Permalink to &quot;中后台管理系统&quot;">​</a></h3><ul><li>路由懒加载 ✅</li><li>虚拟列表(&gt; 100 行表格) ✅</li><li>防抖/节流(搜索、滚动) ✅</li><li>内存清理(图表、定时器) ✅</li></ul><h3 id="移动端-h5" tabindex="-1">移动端 H5 <a class="header-anchor" href="#移动端-h5" aria-label="Permalink to &quot;移动端 H5&quot;">​</a></h3><ul><li>关键 CSS 内联 ✅</li><li>字体 font-display: swap ✅</li><li>图片懒加载 ✅</li><li>首屏骨架屏 ✅</li><li>离线缓存(PWA) ✅</li></ul><h3 id="内容站-博客" tabindex="-1">内容站 / 博客 <a class="header-anchor" href="#内容站-博客" aria-label="Permalink to &quot;内容站 / 博客&quot;">​</a></h3><ul><li>SSG 静态生成 ✅</li><li>图片 AVIF/WebP ✅</li><li>CDN 加速 ✅</li><li>关键路径预取 ✅</li></ul><h3 id="大屏可视化" tabindex="-1">大屏可视化 <a class="header-anchor" href="#大屏可视化" aria-label="Permalink to &quot;大屏可视化&quot;">​</a></h3><ul><li>Web Worker 大数据计算 ✅</li><li>ECharts 异步渲染 / tooltip ✅</li><li>canvas 复用,避免频繁创建 ✅</li><li>7x24 内存监控 ✅</li></ul><h2 id="八、参考文献" tabindex="-1">八、参考文献 <a class="header-anchor" href="#八、参考文献" aria-label="Permalink to &quot;八、参考文献&quot;">​</a></h2><ul><li>《高性能网站建设指南》</li><li><a href="https://web.dev/measure/" target="_blank" rel="noreferrer">web.dev/measure</a></li><li><a href="https://developer.chrome.com/docs/devtools/performance/" target="_blank" rel="noreferrer">Chrome DevTools Performance 文档</a></li></ul>',36)])])}const m=e(o,[["render",t]]);export{b as __pageData,m as default};
